test('invoiceTotals with mixed VAT rates', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
      { sku: 'WORKSHOP-DAY', qty: 1 },
    ],
  });
  assert.equal(result.ok, true);

  const totals = invoiceTotals(result.value);

  const line1Total = 10 * 8500; // 85000, 21% VAT
  const line1Vat = Math.round(85000 * 21 / 100); // 17850

  const line2Total = 1 * 60000; // 60000, 0% VAT
  const line2Vat = 0;

  const expectedSubtotal = line1Total + line2Total; // 145000
  const expectedVat = line1Vat + line2Vat; // 17850
  const expectedTotal = expectedSubtotal + expectedVat; // 162850

  assert.equal(totals.subtotal, expectedSubtotal);
  assert.equal(totals.vat, expectedVat);
  assert.equal(totals.total, expectedTotal);
});

