    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 10 },
      { sku: 'PRINT-A4', qty: 100 },
    ],
  });
  assert.equal(result.ok, true);

  const totals = invoiceTotals(result.value);

  const line1Total = 10 * 8500; // 85000
  const line1Vat = Math.round(85000 * 21 / 100); // 17850

  const line2Total = 100 * 37; // 3700
  const line2Vat = Math.round(3700 * 9 / 100); // 333

  const expectedSubtotal = line1Total + line2Total; // 88700
  const expectedVat = line1Vat + line2Vat; // 18183
  const expectedTotal = expectedSubtotal + expectedVat; // 106883

  assert.equal(totals.subtotal, expectedSubtotal);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, expectedVat);
  assert.equal(totals.total, expectedTotal);
});

test('invoiceTotals with discount and VAT', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
