      { sku: 'DES-HOUR', qty: 10, discountPercent: 20 },
    ],
  });
  assert.equal(result.ok, true);

  const totals = invoiceTotals(result.value);

  const lineTotal = 10 * 8500; // 85000
  const discount = lineTotal * 20 / 100; // 17000
  const baseAmount = lineTotal - discount; // 68000
  const vat = Math.round(baseAmount * 21 / 100); // 14280
  const total = lineTotal - discount + vat; // 85000 - 17000 + 14280 = 82280

  assert.equal(totals.subtotal, lineTotal);
  assert.equal(totals.discount, discount);
  assert.equal(totals.vat, vat);
  assert.equal(totals.total, total);
});

